<?php
require_once __DIR__.'/../../includes/bootstrap.php';require_roles(['ADMIN','RESPONSABLE','AGENT']);$db=Database::connection();$rid=(int)($_GET['recommandation_id']??$_POST['recommandation_id']??0);$s=$db->prepare("SELECT r.*,o.id offre_id,o.prime_totale,d.id demande_id,d.numero_demande,p.nom produit,co.raison_sociale compagnie FROM recommandations r JOIN offres_devis o ON o.id=r.offre_id JOIN demandes_devis d ON d.id=r.demande_id JOIN produits_assurance p ON p.id=o.produit_id JOIN compagnies co ON co.id=p.compagnie_id WHERE r.id=? AND r.statut_validation='validee'");$s->execute([$rid]);$r=$s->fetch()?:exit('Recommandation validée introuvable.');if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$obs=trim((string)($_POST['observations']??''));$next=(int)$db->query('SELECT COALESCE(MAX(id),0)+1 FROM souscriptions')->fetchColumn();$numero='SOU-'.date('Y').'-'.str_pad((string)$next,4,'0',STR_PAD_LEFT);try{$db->beginTransaction();$db->prepare("INSERT INTO souscriptions(offre_id,agent_id,numero_souscription,statut,observations) VALUES(?,?,?,'initiee',?)")->execute([$r['offre_id'],$_SESSION['user']['id'],$numero,$obs?:null]);$sid=(int)$db->lastInsertId();$db->prepare("INSERT INTO suivis_dossiers(souscription_id,utilisateur_id,ancien_statut,nouveau_statut,commentaire) VALUES(?,?,NULL,'initiee','Création de la souscription')")->execute([$sid,$_SESSION['user']['id']]);$db->prepare("UPDATE demandes_devis SET statut='convertie' WHERE id=?")->execute([$r['demande_id']]);$db->commit();audit('SOUSCRIPTION','offre_devis',(int)$r['offre_id']);flash('success','Souscription créée.');redirect('souscriptions/index.php');}catch(PDOException){if($db->inTransaction())$db->rollBack();flash('danger','Cette offre possède déjà une souscription.');redirect('souscriptions/index.php');}}$title='Souscription';require __DIR__.'/../../includes/header.php';?>
<div class="form-shell"><div class="page-heading"><h1 class="h3">Lancer la souscription</h1><a class="btn btn-outline-secondary" href="<?= APP_URL ?>/recommandations/index.php">Retour</a></div><div class="card card-body"><dl class="row"><dt class="col-sm-4">Demande</dt><dd class="col-sm-8"><?= e($r['numero_demande']) ?></dd><dt class="col-sm-4">Offre</dt><dd class="col-sm-8"><?= e($r['compagnie'].' · '.$r['produit']) ?></dd><dt class="col-sm-4">Prime annuelle</dt><dd class="col-sm-8"><?= number_format((float)$r['prime_totale'],0,',',' ') ?> FCFA</dd></dl><form method="post"><?= csrf_field() ?><input type="hidden" name="recommandation_id" value="<?= $rid ?>"><label class="form-label">Observations</label><textarea class="form-control" name="observations" rows="3"></textarea><div class="text-end mt-3"><button class="btn btn-primary">Créer la souscription</button></div></form></div></div><?php require __DIR__.'/../../includes/footer.php'; ?>
